import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { toast } from 'react-toastify';
import axios from 'axios';
import { 
  Upload, 
  Calendar, 
  Play, 
  Clock, 
  CheckCircle, 
  XCircle,
  AlertCircle,
  FileCode
} from 'lucide-react';

const Dashboard = () => {
  const { user } = useAuth();
  const [stats, setStats] = useState({
    totalUploads: 0,
    activeBookings: 0,
    completedBookings: 0
  });
  const [recentUploads, setRecentUploads] = useState([]);
  const [recentBookings, setRecentBookings] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const fetchDashboardData = async () => {
    try {
      const [uploadsRes, bookingsRes] = await Promise.all([
        axios.get('/api/uploads/my-uploads'),
        axios.get('/api/queue/my-bookings')
      ]);

      setRecentUploads(uploadsRes.data.uploads.slice(0, 5));
      setRecentBookings(bookingsRes.data.bookings.slice(0, 5));
      
      setStats({
        totalUploads: uploadsRes.data.uploads.length,
        activeBookings: bookingsRes.data.bookings.filter(b => b.status === 'active').length,
        completedBookings: bookingsRes.data.bookings.filter(b => b.status === 'done').length
      });
    } catch (error) {
      console.error('Error fetching dashboard data:', error);
      toast.error('Failed to load dashboard data');
    } finally {
      setLoading(false);
    }
  };

  const getStatusIcon = (status) => {
    switch (status) {
      case 'active':
        return <CheckCircle className="h-4 w-4 text-green-500" />;
      case 'pending':
        return <Clock className="h-4 w-4 text-yellow-500" />;
      case 'done':
        return <CheckCircle className="h-4 w-4 text-blue-500" />;
      case 'cancelled':
        return <XCircle className="h-4 w-4 text-red-500" />;
      default:
        return <AlertCircle className="h-4 w-4 text-gray-500" />;
    }
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'active':
        return 'text-green-600 bg-green-100';
      case 'pending':
        return 'text-yellow-600 bg-yellow-100';
      case 'done':
        return 'text-blue-600 bg-blue-100';
      case 'cancelled':
        return 'text-red-600 bg-red-100';
      default:
        return 'text-gray-600 bg-gray-100';
    }
  };

  if (loading) {
    return (
      <div className="container py-8">
        <div className="flex items-center justify-center h-64">
          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
        </div>
      </div>
    );
  }

  return (
    <div className="container py-8">
      <div className="mb-8 text-center">
        <h1 className="text-4xl font-bold bg-gradient-to-r from-blue-600 to-purple-600 bg-clip-text text-transparent mb-2">
          Dashboard
        </h1>
        <p className="text-lg text-gray-600">Welcome back, <span className="font-semibold text-gray-800">{user?.username}</span>!</p>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
        <div className="card hover-lift">
          <div className="flex items-center">
            <div className="p-4 bg-gradient-to-br from-blue-500 to-blue-600 rounded-xl shadow-lg">
              <FileCode className="h-6 w-6 text-white" />
            </div>
            <div className="ml-4">
              <p className="text-sm font-medium text-gray-600">Total Uploads</p>
              <p className="text-3xl font-bold text-gray-900">{stats.totalUploads}</p>
            </div>
          </div>
        </div>

        <div className="card hover-lift">
          <div className="flex items-center">
            <div className="p-4 bg-gradient-to-br from-green-500 to-green-600 rounded-xl shadow-lg">
              <Play className="h-6 w-6 text-white" />
            </div>
            <div className="ml-4">
              <p className="text-sm font-medium text-gray-600">Active Bookings</p>
              <p className="text-3xl font-bold text-gray-900">{stats.activeBookings}</p>
            </div>
          </div>
        </div>

        <div className="card hover-lift">
          <div className="flex items-center">
            <div className="p-4 bg-gradient-to-br from-purple-500 to-purple-600 rounded-xl shadow-lg">
              <CheckCircle className="h-6 w-6 text-white" />
            </div>
            <div className="ml-4">
              <p className="text-sm font-medium text-gray-600">Completed</p>
              <p className="text-3xl font-bold text-gray-900">{stats.completedBookings}</p>
            </div>
          </div>
        </div>
      </div>

      {/* Quick Actions */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
        <Link
          to="/queue"
          className="card hover-lift cursor-pointer group"
        >
          <div className="flex items-center">
            <div className="p-4 bg-gradient-to-br from-blue-500 to-blue-600 rounded-xl shadow-lg group-hover:scale-110 transition-transform duration-300">
              <Calendar className="h-6 w-6 text-white" />
            </div>
            <div className="ml-4">
              <h3 className="text-lg font-semibold text-gray-900">Book a Slot</h3>
              <p className="text-gray-600">Reserve time on the field</p>
            </div>
          </div>
        </Link>

        <Link
          to="/control"
          className="card hover-lift cursor-pointer group"
        >
          <div className="flex items-center">
            <div className="p-4 bg-gradient-to-br from-green-500 to-green-600 rounded-xl shadow-lg group-hover:scale-110 transition-transform duration-300">
              <Play className="h-6 w-6 text-white" />
            </div>
            <div className="ml-4">
              <h3 className="text-lg font-semibold text-gray-900">Control Panel</h3>
              <p className="text-gray-600">Run and control your code</p>
            </div>
          </div>
        </Link>

        <div className="card hover-lift group">
          <div className="flex items-center">
            <div className="p-4 bg-gradient-to-br from-orange-500 to-orange-600 rounded-xl shadow-lg group-hover:scale-110 transition-transform duration-300">
              <Upload className="h-6 w-6 text-white" />
            </div>
            <div className="ml-4">
              <h3 className="text-lg font-semibold text-gray-900">Upload Code</h3>
              <p className="text-gray-600">Upload Python files</p>
            </div>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* Recent Uploads */}
        <div className="card card-interactive">
          <div className="flex items-center justify-between mb-6">
            <h3 className="text-xl font-semibold text-gray-900">Recent Uploads</h3>
            <Link
              to="/control"
              className="text-sm text-blue-600 hover:text-blue-500 font-medium transition-colors"
            >
              View all →
            </Link>
          </div>
          {recentUploads.length > 0 ? (
            <div className="space-y-3">
              {recentUploads.map((upload) => (
                <div key={upload.id} className="flex items-center justify-between p-3 bg-gray-50 rounded-lg">
                  <div className="flex items-center">
                    <FileCode className="h-4 w-4 text-gray-500 mr-3" />
                    <div>
                      <p className="text-sm font-medium text-gray-900">
                        {upload.original_filename}
                      </p>
                      <p className="text-xs text-gray-500">
                        {new Date(upload.uploaded_at).toLocaleDateString()}
                      </p>
                    </div>
                  </div>
                  <span className="text-xs text-gray-500">
                    {(upload.file_size / 1024).toFixed(1)} KB
                  </span>
                </div>
              ))}
            </div>
          ) : (
            <p className="text-gray-500 text-center py-4">No uploads yet</p>
          )}
        </div>

        {/* Recent Bookings */}
        <div className="card card-interactive">
          <div className="flex items-center justify-between mb-6">
            <h3 className="text-xl font-semibold text-gray-900">Recent Bookings</h3>
            <Link
              to="/queue"
              className="text-sm text-blue-600 hover:text-blue-500 font-medium transition-colors"
            >
              View all →
            </Link>
          </div>
          {recentBookings.length > 0 ? (
            <div className="space-y-3">
              {recentBookings.map((booking) => (
                <div key={booking.id} className="flex items-center justify-between p-3 bg-gray-50 rounded-lg">
                  <div className="flex items-center">
                    {getStatusIcon(booking.status)}
                    <div className="ml-3">
                      <p className="text-sm font-medium text-gray-900">
                        {booking.field_name || 'Main Field'}
                      </p>
                      <p className="text-xs text-gray-500">
                        {new Date(booking.start_time).toLocaleDateString()} - {new Date(booking.end_time).toLocaleDateString()}
                      </p>
                    </div>
                  </div>
                  <span className={`px-2 py-1 text-xs rounded-full ${getStatusColor(booking.status)}`}>
                    {booking.status}
                  </span>
                </div>
              ))}
            </div>
          ) : (
            <p className="text-gray-500 text-center py-4">No bookings yet</p>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
